// Propuesta 2: every project folder (generated by scripts/build-all-projects.mjs).
// Curated projects from projects.ts keep their hand-edited copy and go first.
import rawJson from './all-projects.json';
import { asset } from '../lib/asset';
import { projects as curated, type Project } from './projects';

const raw = rawJson.map(p => ({ ...p, images: p.images.map(asset) }));

const ALIAS: Record<string, string> = { babyprotec: 'baby-protec' };

const bySlug = new Map(raw.map(p => [p.slug, p]));

const featured: Project[] = curated.map(c => {
  const r = bySlug.get(ALIAS[c.slug] ?? c.slug);
  // Use the larger image set from the full build when available
  return r && r.images.length > c.images.length ? { ...c, images: r.images } : c;
});
const featuredSlugs = new Set(curated.map(c => ALIAS[c.slug] ?? c.slug));

const rest: Project[] = raw
  .filter(p => !featuredSlugs.has(p.slug))
  .map(p => ({
    slug: p.slug as Project['slug'],
    title: p.title,
    category: p.category,
    client: '',
    summary: p.summary,
    body: p.body.slice(0, 3),
    result: '',
    services: p.services,
    images: p.images,
  }));

export const allProjects: Project[] = [...featured, ...rest];
